// 原成年人本人请求合同：保正常provider/具名本人SAY，拒玩家/第三人/choice冒本人自愿。
#include "resident/domains/family/adult_adoption_source.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {Integer checks=0;void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}}
int main(int argc,char** argv){try{const bool old=argc==2&&StableId(argv[1])=="--expect-legacy-gap";auto owner=std::make_shared<CommonCatalog>();auto& common=*owner;common.actor_ids={"adopter","candidate"};common.places.insert("home",{"home","town",{}});common.roles.insert("role",{"role","candidate","home",{},{},{}});InteractionCatalog interaction;interaction.common=owner;DialogueDefinition talk;talk.id="dialogue";talk.context_role="role";talk.entry="request";DialogueNode node;node.id="request";node.kind="say";node.speaker="$provider";talk.nodes.push_back(node);interaction.dialogues.push_back(talk);AdultAdoptionRequestCatalog requests;requests.enabled=true;requests.definitions.insert("request",{"request","adopter","candidate","dialogue","request",1});CommonState state;state.identity.world_id[0]=1;state.metadata.scenario_id="scene";state.identity.tick=20;for(const auto* id:{"adopter","candidate"}){ActorRecord a;a.id=id;a.alive=true;a.birth_tick=-20*720;state.actors.insert(id,a);}AdultAdoptionAgreement a;a.request_id="request";a.adopter_actor_id="adopter";a.adoptee_actor_id="candidate";a.dialogue_id="dialogue";a.node_id="request";a.node_kind="say";a.session_id="interaction:1";a.scenario_id="scene";a.world_id=state.identity.world_id;a.context={"home","candidate","role"};a.accepted_tick=20;a.adopter_birth_tick=a.adoptee_birth_tick=-20*720;
 const auto before=encode_common_state(state);check(validate_adult_adoption_request_catalog(requests,common,interaction).ok,"original provider request catalog");check(validate_adult_adoption_agreement_source(state,common,interaction,requests,a).ok,"original provider cold agreement");interaction.dialogues[0].nodes[0].speaker="candidate";check(validate_adult_adoption_request_catalog(requests,common,interaction).ok,"explicit actual candidate speaker");check(validate_adult_adoption_agreement_source(state,common,interaction,requests,a).ok,"explicit actual candidate cold source");
 for(const StableId speaker:{"$player","adopter","stranger"}){interaction.dialogues[0].nodes[0].speaker=speaker;check(validate_adult_adoption_request_catalog(requests,common,interaction).ok==old,"other person's SAY is not candidate request");check(validate_adult_adoption_agreement_source(state,common,interaction,requests,a).ok==old,"cold source rejects other person's SAY");}
 interaction.dialogues[0].nodes[0].speaker="$provider";interaction.dialogues[0].nodes[0].kind="choice";a.node_kind="choice";check(validate_adult_adoption_request_catalog(requests,common,interaction).ok==old,"choice cannot speak for candidate");check(validate_adult_adoption_agreement_source(state,common,interaction,requests,a).ok==old,"cold choice cannot be candidate consent");check(compare_boundary(before,encode_common_state(state)).exact(),"validation changed actor/state bytes");std::cout<<(old?"ADULT_ADOPTION_LEGACY_GAP ":"ADULT_ADOPTION_SPEAKER ")<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
